// Consolidate the diagram description, documentation text, and infrastructure
// config into a single context block, and surface a few quick preliminary
// signals so the AI agent has something concrete to anchor on.
const config = $input.item.json;

const diagramDescription = config.diagramDescription || '';
const documentText = config.documentText || '';
const infrastructureConfig = config.infrastructureConfig || '';

const sourceDocumentCount = [diagramDescription, documentText, infrastructureConfig].filter(s => s && s.trim().length > 0).length;

const preliminarySignals = [];
const combined = `${diagramDescription}\n${documentText}\n${infrastructureConfig}`;

if (/0\.0\.0\.0\/0/.test(combined)) preliminarySignals.push('Open CIDR (0.0.0.0/0) reference found - review ingress/egress scope');
if (/public[-_ ]?read|acl\s*[:=]\s*["']?public/i.test(combined)) preliminarySignals.push('Publicly readable storage reference found');
if (/http:\/\//.test(combined) && !/https:\/\//.test(combined)) preliminarySignals.push('Plaintext HTTP reference found with no HTTPS counterpart');
if (/(password|secret|api[_-]?key)\s*[:=]\s*["'][^"']+["']/i.test(combined)) preliminarySignals.push('Possible hardcoded credential/secret pattern found');
if (!/mfa|multi-factor|2fa/i.test(combined)) preliminarySignals.push('No mention of multi-factor authentication found');

const architectureContext = [
  diagramDescription ? `--- Diagram Description ---\n${diagramDescription}` : null,
  documentText ? `--- Documentation ---\n${documentText}` : null,
  infrastructureConfig ? `--- Infrastructure Config ---\n${infrastructureConfig}` : null
].filter(Boolean).join('\n\n');

return [{
  json: {
    ...config,
    architectureContext,
    preliminarySignals,
    sourceDocumentCount
  }
}];

parameters.text:
=You are a senior security architect performing a design review. Assess the following architecture context against these frameworks: {{ $json.reviewFrameworks.join(', ') }}

Preliminary automated signals already detected (verify and expand on these, do not just repeat them):
{{ $json.preliminarySignals.length ? $json.preliminarySignals.map(s => '- ' + s).join('\n') : '- none' }}

Architecture context ({{ $json.sourceDocumentCount }} source document(s)):
{{ $json.architectureContext }}

Review the architecture for weaknesses across authentication, authorization/IAM, network segmentation, data encryption (in transit and at rest), secrets management, logging/monitoring, and blast-radius/least-privilege design. Pay particular attention to these categories: {{ $json.criticalCategories.join(', ') }}.

Return ONLY a JSON object with keys:
- executiveSummary: a 3-5 sentence overview of the architecture's security posture
- overallRiskScore: a number 0-100 (higher = riskier)
- findings: an array of objects, each with { category, severity ('Info'|'Warning'|'Critical'), title, description, affectedComponent, recommendation }

No markdown fences, no commentary outside the JSON object.

