// Parse the agent's structured findings, validate the shape, and compute
// a highest-severity marker for downstream routing.
const item = $input.item.json;
const raw = item.output || item.text || item.response || '{}';

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    executiveSummary: 'AI response could not be parsed automatically. Manual review required.',
    overallRiskScore: 50,
    findings: [{
      category: 'Review Process',
      severity: 'Warning',
      title: 'Automated parsing failed',
      description: String(raw).slice(0, 500),
      affectedComponent: 'N/A',
      recommendation: 'Have a security reviewer manually read the raw AI output.'
    }]
  };
}

const findings = Array.isArray(parsed.findings) ? parsed.findings : [];
const severityRank = { 'Critical': 3, 'Warning': 2, 'Info': 1 };
let highestSeverity = 'Info';
for (const f of findings) {
  const s = f.severity || 'Info';
  if ((severityRank[s] || 0) > (severityRank[highestSeverity] || 0)) highestSeverity = s;
}

return {
  json: {
    ...item,
    executiveSummary: parsed.executiveSummary || '',
    overallRiskScore: typeof parsed.overallRiskScore === 'number' ? parsed.overallRiskScore : 0,
    findings,
    findingsCount: findings.length,
    highestSeverity
  }
};

// Parse the critic agent's verdicts and deterministically reconcile them against
// the first-pass findings: drop confirmed false positives (keeping them in an audit
// list), apply severity corrections, and replace the risk score with the critic's
// revised score. Fails safe on parse errors by keeping the first-pass findings as-is.
const item = $input.item.json;
const raw = item.output || item.text || item.response || '{}';

let critic;
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  critic = JSON.parse(cleaned);
} catch (e) {
  return {
    json: {
      ...item,
      criticApplied: false,
      criticParseError: e.message,
      dismissedFindings: [],
      dismissedFindingsCount: 0,
      firstPassRiskScore: item.overallRiskScore,
      criticOverallAssessment: 'Critic output could not be parsed; first-pass findings were kept unmodified.',
      criticConfidenceAvg: null
    }
  };
}

const originalFindings = item.findings || [];
const verdicts = Array.isArray(critic.validatedFindings) ? critic.validatedFindings : [];
const severityRank = { 'Critical': 3, 'Warning': 2, 'Info': 1 };

// Match critic verdicts back to original findings by title (case-insensitive) since
// the critic references findings by title rather than array index, which is more
// robust to re-ordering. A finding with no matching verdict is kept as-is but flagged
// as unreviewed (fail open on coverage gaps, fail closed only on explicit
// false_positive verdicts).
function normalizeTitle(t) { return String(t || '').toLowerCase().trim(); }
const verdictByTitle = new Map(verdicts.map(v => [normalizeTitle(v.title), v]));

const confirmedFindings = [];
const dismissedFindings = [];

for (const f of originalFindings) {
  const v = verdictByTitle.get(normalizeTitle(f.title));

  if (!v) {
    confirmedFindings.push({ ...f, criticVerdict: 'unreviewed', criticConfidence: null, criticNotes: '' });
    continue;
  }

  if (v.verdict === 'false_positive') {
    dismissedFindings.push({ ...f, criticReasoning: v.critique || v.reasoning || 'Marked as false positive by critic pass.' });
    continue;
  }

  confirmedFindings.push({
    ...f,
    severity: v.adjustedSeverity && severityRank.hasOwnProperty(v.adjustedSeverity) ? v.adjustedSeverity : f.severity,
    criticVerdict: v.verdict || 'confirmed',
    criticConfidence: typeof v.confidenceScore === 'number' ? Math.min(1, Math.max(0, v.confidenceScore)) : null,
    criticNotes: v.critique || v.reasoning || ''
  });
}

let highestSeverity = 'Info';
for (const f of confirmedFindings) {
  const s = f.severity || 'Info';
  if ((severityRank[s] || 0) > (severityRank[highestSeverity] || 0)) highestSeverity = s;
}

const revisedRiskScore = typeof critic.revisedRiskScore === 'number'
  ? Math.min(100, Math.max(0, critic.revisedRiskScore))
  : item.overallRiskScore;

const confidenceScores = confirmedFindings.map(f => f.criticConfidence).filter(c => typeof c === 'number');
const criticConfidenceAvg = confidenceScores.length
  ? Math.round((confidenceScores.reduce((a, b) => a + b, 0) / confidenceScores.length) * 100) / 100
  : null;

return {
  json: {
    ...item,
    criticApplied: true,
    findings: confirmedFindings,
    findingsCount: confirmedFindings.length,
    dismissedFindings,
    dismissedFindingsCount: dismissedFindings.length,
    highestSeverity,
    overallRiskScore: revisedRiskScore,
    firstPassRiskScore: item.overallRiskScore,
    criticOverallAssessment: critic.overallAssessment || '',
    criticConfidenceAvg
  }
};

// Compile the final security review summary report: executive summary, second-pass
// validation notes, findings grouped by severity, and a prioritized remediation roadmap.
const item = $input.item.json;
const findings = item.findings || [];

const severityOrder = ['Critical', 'Warning', 'Info'];
const grouped = severityOrder.reduce((acc, s) => { acc[s] = findings.filter(f => (f.severity || 'Info') === s); return acc; }, {});

const sections = severityOrder.map(sev => {
  const items = grouped[sev];
  if (!items.length) return null;
  const lines = items.map((f, i) => `${i + 1}. [${f.category || 'General'}] ${f.title} - ${f.description} (Affected: ${f.affectedComponent || 'N/A'}). Recommendation: ${f.recommendation}` + (f.criticConfidence != null ? ` [critic confidence: ${f.criticConfidence}]` : ''));
  return `## ${sev} Findings (${items.length})\n${lines.join('\n')}`;
}).filter(Boolean);

const remediationRoadmap = findings
  .slice()
  .sort((a, b) => severityOrder.indexOf(a.severity || 'Info') - severityOrder.indexOf(b.severity || 'Info'))
  .map((f, i) => `${i + 1}. (${f.severity}) ${f.recommendation}`);

const validationSection = item.criticApplied
  ? `## Second-Pass Validation\n`
    + `First-pass risk score: ${item.firstPassRiskScore}/100 -> Revised risk score: ${item.overallRiskScore}/100\n`
    + `Average critic confidence on confirmed findings: ${item.criticConfidenceAvg != null ? item.criticConfidenceAvg : 'n/a'}\n`
    + `Critic assessment: ${item.criticOverallAssessment || 'n/a'}\n`
    + `False positives dismissed: ${item.dismissedFindingsCount || 0}`
    + (item.dismissedFindings && item.dismissedFindings.length
        ? `\n\n### Dismissed Findings (audit trail)\n` + item.dismissedFindings.map((f, i) => `${i + 1}. [${f.category || 'General'}] ${f.title} - ${f.criticReasoning}`).join('\n')
        : '')
  : `## Second-Pass Validation\nCritic pass did not run or could not be parsed (${item.criticParseError || 'unknown reason'}); findings reflect the first-pass review only.`;

const reportMarkdown = `# Security Architecture Review Summary\n\n`
  + `**Reviewed frameworks:** ${item.reviewFrameworks.join(', ')}\n`
  + `**Overall risk score:** ${item.overallRiskScore}/100\n`
  + `**Highest severity:** ${item.highestSeverity}\n\n`
  + `## Executive Summary\n${item.executiveSummary}\n\n`
  + validationSection
  + `\n\n`
  + sections.join('\n\n')
  + `\n\n## Remediation Roadmap\n${remediationRoadmap.join('\n')}`;

return {
  json: {
    ...item,
    reportMarkdown,
    generatedAt: new Date().toISOString()
  }
};
